"""File-based session storage. One folder per session under data/sessions/<id>/."""
import json
import shutil
import threading
import time
import uuid
from pathlib import Path

from . import config

_lock = threading.RLock()

STAGES = ["audio", "transcript", "frames", "captions", "summary"]
STAGE_LABELS = {
    "audio": "Extracting audio",
    "transcript": "Transcribing",
    "frames": "Capturing screenshots",
    "captions": "Reading screenshots",
    "summary": "Writing summary & chapters",
}


def sdir(sid: str) -> Path:
    # ids are generated by us; guard against path tricks anyway
    if not sid or any(c in sid for c in "/\\.") or len(sid) > 40:
        raise ValueError("bad session id")
    return config.SESSIONS_DIR / sid


def _read(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _write(path: Path, data):
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(data, indent=1, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def create(title: str, video_path: str, options: dict, copied: bool) -> dict:
    sid = time.strftime("%Y%m%d-%H%M%S-") + uuid.uuid4().hex[:6]
    d = sdir(sid)
    (d / "frames").mkdir(parents=True, exist_ok=True)
    meta = {
        "id": sid,
        "title": title,
        "created": time.time(),
        "video_path": video_path,
        "video_copied": copied,
        "duration": 0,
        "status": "queued",
        "stage": None,
        "progress": 0.0,
        "message": "Waiting to start",
        "error": None,
        "stages": {s: "pending" for s in STAGES},
        "options": options,
        "runbook": {"state": "none", "chars": 0, "error": None, "updated": None},
    }
    _write(d / "meta.json", meta)
    return meta


def get(sid: str) -> dict | None:
    p = sdir(sid) / "meta.json"
    if not p.exists():
        return None
    return _read(p, None)


def update(sid: str, **fields) -> dict:
    with _lock:
        meta = get(sid)
        if meta is None:
            raise KeyError(sid)
        for k, v in fields.items():
            if k == "stages":
                meta["stages"].update(v)
            elif k == "runbook":
                meta["runbook"].update(v)
            else:
                meta[k] = v
        _write(sdir(sid) / "meta.json", meta)
        return meta


def list_all() -> list[dict]:
    config.ensure_dirs()
    out = []
    for d in config.SESSIONS_DIR.iterdir():
        m = _read(d / "meta.json", None) if d.is_dir() else None
        if m:
            out.append(m)
    out.sort(key=lambda m: m["created"], reverse=True)
    return out


def delete(sid: str):
    d = sdir(sid)
    if d.exists():
        shutil.rmtree(d, ignore_errors=True)


# ---- artifacts -------------------------------------------------------------

def read_json(sid: str, name: str, default):
    return _read(sdir(sid) / name, default)


def write_json(sid: str, name: str, data):
    with _lock:
        _write(sdir(sid) / name, data)


def read_text(sid: str, name: str) -> str:
    p = sdir(sid) / name
    return p.read_text(encoding="utf-8") if p.exists() else ""


def write_text(sid: str, name: str, text: str):
    p = sdir(sid) / name
    tmp = p.with_suffix(p.suffix + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    tmp.replace(p)


def frames_dir(sid: str) -> Path:
    return sdir(sid) / "frames"


def recover_interrupted():
    """Sessions left 'running' by a crash/restart are marked so the user can resume."""
    for m in list_all():
        changes = {}
        if m["status"] in ("running", "queued"):
            changes.update(status="error", error="Interrupted (app was closed). Click Resume.",
                           message="Interrupted")
            stages = {k: ("pending" if v == "running" else v) for k, v in m["stages"].items()}
            changes["stages"] = stages
        if m.get("runbook", {}).get("state") in ("running", "queued"):
            changes["runbook"] = {"state": "error", "error": "Interrupted. Generate again."}
        if changes:
            update(m["id"], **changes)
